function renderAttachmentTrigger(
  props: Partial<Record<keyof ComponentProps<typeof AttachmentTrigger>, unknown>> = {},
) {
  cleanup()
  render(
    <Attachment size="sm">
      <AttachmentTrigger data-subject {...(props as ComponentProps<typeof AttachmentTrigger>)} />
    </Attachment>,
  )
  return document.querySelector('[data-subject]')?.closest('[data-slot="attachment-trigger"]')
}

function classesOfAttachmentTrigger(
  props: Partial<Record<keyof ComponentProps<typeof AttachmentTrigger>, unknown>> = {},
) {
  return renderAttachmentTrigger(props)?.getAttribute('class')?.split(' ') ?? []
}

describe('AttachmentTrigger', () => {
  it('renders [data-slot="attachment-trigger"] with its classes', () => {
    expect(classesOfAttachmentTrigger()).toEqual(expect.arrayContaining([styles.attachmentTrigger]))
  })

  it('appends a consumer className last', () => {
    renderAttachmentTrigger({ className: 'consumer' })
    const element = document.querySelector('.consumer')
    expect(element?.getAttribute('class')?.split(' ').at(-1)).toBe('consumer')
  })

  it("renders as upstream's example uses it (2)", () => {
    cleanup()
    render(
      <Attachment>
        <AttachmentTrigger data-subject />
      </Attachment>,
    )
    expect(document.querySelector('[data-subject]')).not.toBeNull()
  })

  it("renders as upstream's example uses it (3)", () => {
    cleanup()
    render(
      <AttachmentGroup>
        <Attachment orientation="vertical">
          <AttachmentTrigger data-subject />
        </Attachment>
      </AttachmentGroup>,
    )
    expect(document.querySelector('[data-subject]')).not.toBeNull()
  })

  it("renders as upstream's example uses it (4)", () => {
    cleanup()
    render(
      <Attachment>
        <AttachmentTrigger data-subject aria-label="Preview research-summary.pdf" />
      </Attachment>,
    )
    expect(document.querySelector('[data-subject]')).not.toBeNull()
  })
})

